"""Execute the C stencils generated by Devito using batched CUDA graphs.

This is a local CUDA execution adapter, not DevitoPRO or native CUDA codegen.
The six update bodies are extracted verbatim from the existing Devito CPU
operator. This adapter supplies iteration dispatch, independent batch offsets,
single-plane buffer reuse, fusion of independent stress/displacement updates
and output copies. Physical coefficients and source preparation remain shared.
"""
import hashlib
import re
import time

import numpy as np


def _body(text, pattern):
    match = re.search(pattern, text)
    if match is None:
        raise RuntimeError('unsupported Devito generated loop structure')
    start = text.index('{', match.end())
    depth = 1
    for end in range(start + 1, len(text)):
        depth += (text[end] == '{') - (text[end] == '}')
        if depth == 0:
            return text[start + 1:end]
    raise RuntimeError('unbalanced Devito generated loop')


class DevitoCUDAGraph:
    def __init__(self, cfg, batch_size):
        import cupy as cp
        from .physics import DevitoElastic
        self.cp = cp
        self.cfg = cfg
        self.batch_size = batch_size
        self.base = DevitoElastic(cfg)
        self.n = cfg['grid']['n']
        self.frames = cfg['grid']['frames']
        self.arrays = {**self.base.material, **self.base.fields,
                       'src': self.base.src, 'src_coords': self.base.src.coordinates}
        self.shapes = {k: tuple(v.data_with_halo.shape) for k, v in self.arrays.items()}
        # Each update phase reads the old value only at its own output point.
        # Phase barriers protect neighbor reads, so one plane is sufficient.
        for name in self.base.fields:
            self.shapes[name] = (1,) + self.shapes[name][1:]
        self.names = sorted(self.arrays)
        self.h, self.w = self.shapes['lam']
        generated = str(self.base.op.ccode)
        self.devito_source_sha256 = hashlib.sha256(generated.encode()).hexdigest()
        source = self._cuda_source(generated)
        self.cuda_source = source
        self.cuda_source_sha256 = hashlib.sha256(source.encode()).hexdigest()
        estimated = batch_size * (sum(np.prod(s) for s in self.shapes.values()) +
                                 self.n*self.n*self.frames*2 + self.frames*self.n*2) * 4
        free, _ = cp.cuda.runtime.memGetInfo()
        if estimated + 256*1024**2 > free:
            raise MemoryError('insufficient free GPU memory for this generation batch')
        self.gpu = {k: cp.zeros((batch_size,) + shape, dtype=cp.float32)
                    for k, shape in self.shapes.items()}
        self.output = cp.zeros((batch_size, self.n, self.n, self.frames, 2), dtype=cp.float32)
        self.boundary = cp.zeros((batch_size, self.frames, self.n, 2), dtype=cp.float32)
        module = cp.RawModule(code=source, options=('--std=c++11', '--fmad=false'))
        module.compile()
        kernels = [module.get_function(f'eno_stage_{i}') for i in range(6)]
        record = module.get_function('eno_record')
        self.module = module
        pointers = tuple(self.gpu[k] for k in self.names)
        nz, nx = self.base.grid.shape
        dense = ((nx+31)//32, (nz+7)//8, batch_size)
        surface = ((nx+127)//128, 1, batch_size)
        self.stream = cp.cuda.Stream(non_blocking=True)
        with self.stream:
            self.stream.begin_capture()
            for name in self.base.fields:
                self.gpu[name].fill(0)
            self.output.fill(0)
            self.boundary.fill(0)
            for time in range(self.base.steps):
                args = pointers + (np.int32(time),)
                for i, kernel in enumerate(kernels):
                    if i == 5:
                        continue  # Displacement is fused into the stress phase.
                    if i == 3:
                        kernel((1, 1, batch_size), (1,), args)
                    elif i in [1, 4]:
                        kernel(surface, (128,), args)
                    else:
                        kernel(dense, (32, 8), args)
                if (time + 1) % self.base.substeps == 0:
                    frame = (time + 1) // self.base.substeps
                    record(((self.n*self.n+127)//128, 1, batch_size), (128,),
                           pointers + (self.output, self.boundary, np.int32(time), np.int32(frame)))
            self.graph = self.stream.end_capture()
        self.last_diagnostics = {}

    def _cuda_source(self, generated):
        sections = re.findall(r'START\(section(\d+)\)(.*?)STOP\(section\1,timers\)',
                              generated, flags=re.S)
        if [int(i) for i, _ in sections] != list(range(6)):
            raise RuntimeError('Devito generated stencil changed; CUDA adapter needs review')
        params = ', '.join('float *base_' + k for k in self.names)
        views = []
        for name in self.names:
            shape = self.shapes[name]
            dims = ''.join(f'[{s}]' for s in shape[1:])
            size = int(np.prod(shape))
            views.append(f'float (*{name}){dims} = (float (*){dims})(base_{name} + batch*{size});')
        nz, nx = self.base.grid.shape
        constants = (f'const int batch=blockIdx.z, t0=0, t1=0;\n' +
                     f'const int z_m=0,z_M={nz-1},x_m=0,x_M={nx-1};\n' +
                     f'const float h_x={self.base.dx}f,h_z={self.base.dx}f,o_x=0.f,o_z=0.f;\n' +
                     '\n'.join(views))
        kernels = []
        displacement = _body(sections[5][1], r'for \(int x = [^\n]+\)')
        for index, section in sections:
            i = int(index)
            if i == 3:
                body = _body(section, r'for \(int p_src = [^\n]+\)')
                body = re.sub(r'^\s*#pragma[^\n]*', '', body, flags=re.M)
                dispatch = 'const int p_src=0;'
                guard = 'true'
            else:
                body = _body(section, r'for \(int x = [^\n]+\)')
                if i == 2:
                    # Both bodies consume the same completed velocity update;
                    # displacement neither reads nor writes stress/source data.
                    body += displacement
                dispatch = 'const int x=blockIdx.x*blockDim.x+threadIdx.x;'
                guard = 'x<=x_M'
                if i in [0, 2, 5]:
                    dispatch += 'const int z=blockIdx.y*blockDim.y+threadIdx.y;'
                    guard += ' && z<=z_M'
            kernels.append(f'extern "C" __global__ void eno_stage_{i}({params}, const int time)' +
                           '{\n' + constants + '\n' + dispatch + '\nif (' + guard + ') {\n' + body + '\n}}')
        r = self.cfg['fd']['refinement']
        top = self.base.top + 2
        pad = self.base.pad + 2
        n, frames = self.n, self.frames
        # These are copies of collocated displacement and boundary diagnostics;
        # all numerical update expressions above come from Devito itself.
        record = f'''
extern "C" __global__ void eno_record({params}, float *out, float *boundary,
                                      const int time, const int frame) {{
{constants}
const int q=blockIdx.x*blockDim.x+threadIdx.x;
if(q>={n*n}) return;
const int qz=q/{n}, qx=q%{n}, z={top}+{r}*qz, x={pad}+{r}*qx;
const int dest=((batch*{n*n}+q)*{frames}+frame)*2;
out[dest]=ux[t1][z][x];out[dest+1]=uz[t1][z][x];
if(qz==0) {{
const int bd=((batch*{frames}+frame)*{n}+qx)*2;
boundary[bd]=szz[t1][{top}][x];
boundary[bd+1]=sxz[t1][{top-1}][x]+sxz[t1][{top}][x];
}}
}}
'''
        return '\n'.join(kernels) + record

    def run(self, velocities, locations, source_scale=1.):
        begin = time.perf_counter()
        velocities = np.asarray(velocities)
        locations = np.asarray(locations)
        n, batch = self.n, self.batch_size
        if velocities.shape != (batch, 2, n, n) or locations.shape != (batch, 2):
            raise ValueError('GPU batch requires velocities [B,2,n,n], locations [B,2]')
        if np.any(locations < 1) or np.any(locations > n-2):
            raise ValueError('source outside interior')
        upload = {k: np.empty((batch,) + self.shapes[k], dtype='float32')
                  for k in self.base.material}
        upload['src'] = np.empty((batch,) + self.shapes['src'], dtype='float32')
        upload['src_coords'] = np.empty((batch,) + self.shapes['src_coords'], dtype='float32')
        r = self.cfg['fd']['refinement']
        for i, (velocity, location) in enumerate(zip(velocities, locations)):
            self.base.prepare(velocity, source_scale)
            self.base.src.coordinates.data[0] = [(self.base.top+location[0]*r)*self.base.dx,
                                                 (self.base.pad+location[1]*r)*self.base.dx]
            for k, data in upload.items():
                data[i] = self.arrays[k].data_with_halo
        prepared = time.perf_counter()
        with self.stream:
            for k, data in upload.items():
                self.gpu[k].set(data, stream=self.stream)
            self.graph.launch(stream=self.stream)
        self.stream.synchronize()
        executed = time.perf_counter()
        result = self.output.get()
        boundary = self.boundary.get()
        if not np.isfinite(result).all():
            raise FloatingPointError('non-finite Devito CUDA displacement')
        self.last_diagnostics = dict(
            backend='devito', device='cuda', execution='devito_generated_cuda_graph',
            batch_size=batch, space_order=2, dt_s=self.base.dt, dx_m=self.base.dx,
            top_normal_stress_max=float(np.max(np.abs(boundary[..., 0]))),
            top_shear_antisymmetry_error=float(np.max(np.abs(boundary[..., 1]))),
            devito_source_sha256=self.devito_source_sha256,
            cuda_source_sha256=self.cuda_source_sha256)
        self.last_diagnostics['timings_s'] = dict(prepare=prepared-begin,
                                                 upload_and_graph=executed-prepared,
                                                 download_and_check=time.perf_counter()-executed)
        return result
